    def has_1pos_and_kwonly(func):
        """Check if function has exactly 1 positional argument and keyword-only arguments."""
        try:
            spec = inspect.signature(func)
        except (ValueError, TypeError):
            return False

        params = list(spec.parameters.values())
        if not params:
            return False

        # Check first parameter is positional (POSITIONAL_ONLY or POSITIONAL_OR_KEYWORD)
        first = params[0]
        if first.kind not in (first.POSITIONAL_ONLY, first.POSITIONAL_OR_KEYWORD):
            return False

        # Check remaining parameters are all keyword-only
        for param in params[1:]:
            if param.kind != param.KEYWORD_ONLY:
                return False

        # Must have at least one keyword-only argument
        return len(params) > 1

